/* ===== Blueprint brief: one builder for the printout, the emails and the team notice =====
   Runs in the browser (window.BYBrief) and in Cloudflare Functions (module export). No DOM use. */
var BYBrief=(function(){
'use strict';
var STAGES=[['Understand',['DISC','ASSESS']],['Design',['ARCH','PLAN']],['Build',['DEV','CONF','INTEG','MIGR']],['Prove',['SEC','TEST']],['Launch',['DEPLOY','HAND']],['Run',['MON']]];
var MON=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function esc(s){return String(s==null?'':s).replace(/[<>&"']/g,function(c){return {'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&#39;'}[c]})}
function parseDay(iso){var m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(iso||'');return m?new Date(Date.UTC(+m[1],+m[2]-1,+m[3])):null}
function fmt(d){return d.getUTCDate()+' '+MON[d.getUTCMonth()]+' '+d.getUTCFullYear()}
function addWorkDays(start,days){var d=new Date(start.getTime());d.setUTCDate(d.getUTCDate()+Math.round(days/5*7));return d}
function wk(a,b){var x=Math.max(1,Math.round(a)+1),y=Math.max(x,Math.round(b));return x===y?'Week '+x:'Weeks '+x+'–'+y}
function stages(bp){
  var groupOf={},out=[];STAGES.forEach(function(s){s[1].forEach(function(ph){groupOf[ph]=s[0]})});
  STAGES.forEach(function(s){var ps=bp.phases.filter(function(p){return s[1].indexOf(p.phase_id)>-1});if(!ps.length)return;
    var ag={};bp.activities.forEach(function(a){if(groupOf[a.phase_id]===s[0]&&a.assigned_agent)ag[a.assigned_agent]=1});
    out.push({name:s[0],a:Math.min.apply(null,ps.map(function(p){return p.start_day}))/5,b:Math.max.apply(null,ps.map(function(p){return p.end_day}))/5,agents:Object.keys(ag).length})});
  return out;
}
/* plain data the three outputs share */
function model(bp,startISO){
  var P=bp.project,D=P.estimated_duration,v=bp.visual||{components:[],fixes:{}},start=parseDay(startISO);
  var label={};bp.problems.forEach(function(p){label[p.problem_id]=p.description});
  var fixBy={};Object.keys(v.fixes||{}).forEach(function(p){(fixBy[v.fixes[p]]=fixBy[v.fixes[p]]||[]).push(label[p])});
  return {
    title:P.proposed_solution,category:P.title,complexity:P.complexity,minW:D.minimum_weeks,maxW:D.maximum_weeks,
    brief:P.problem_statement,summary:bp.solution.summary,
    problems:bp.problems.map(function(p){return {text:p.description,why:p.operational_consequence,stated:p.source==='stated'}}),
    parts:v.components.filter(function(c){return c.lane!=='plan'}).map(function(c){return {name:c.name,fixes:(fixBy[c.id]||[]).filter(Boolean)}}),
    stages:stages(bp).map(function(s){return {name:s.name,when:wk(s.a,s.b),agents:s.agents}}),
    milestones:bp.delivery.milestones.map(function(m){return {name:m.name,when:start?fmt(addWorkDays(start,m.week*5)):'Week '+Math.max(1,Math.round(m.week))}}),
    start:start?fmt(start):'',coverage:bp.automation.coverage_percentage,
    gates:(v.gates||[]).map(function(g){return g.label}),
    metrics:bp.business_impact.measurable_metrics.map(function(m){return m.metric}),
    outcomes:(bp.business_impact.expected_outcomes||[]).map(function(o){return typeof o==='string'?o:o.outcome}).filter(Boolean),
    assumptions:(bp.delivery.assumptions||[]).map(function(a){return typeof a==='string'?a:(a.description||a.text||'')}).filter(Boolean),
    risks:(bp.delivery.risks||[]).map(function(r){return r.description+(r.mitigation?' Mitigation: '+r.mitigation:'')}),
    agents:bp.agents.map(function(a){return a.name}),people:bp.resources.human_roles
  };
}
var INK='#1E1B4B',MUTE='#5B5878',IND='#4F46E5',LINE='#E6E3F5';
function h2(t){return '<h2 style="font:600 15px/1.3 Inter,Arial,sans-serif;color:'+INK+';margin:22px 0 8px">'+esc(t)+'</h2>'}
function ul(items){return '<ul style="margin:0;padding-left:18px;font:14px/1.55 Inter,Arial,sans-serif;color:'+INK+'">'+items.map(function(i){return '<li style="margin:3px 0">'+i+'</li>'}).join('')+'</ul>'}
function rows(items){return '<table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse;font:14px/1.45 Inter,Arial,sans-serif">'+items.map(function(r){return '<tr><td style="padding:6px 0;border-bottom:1px solid '+LINE+';color:'+INK+';font-weight:600">'+esc(r[0])+'</td><td style="padding:6px 0;border-bottom:1px solid '+LINE+';color:'+MUTE+';text-align:right">'+esc(r[1])+'</td></tr>'}).join('')+'</table>'}
/* one-page brief: what we heard, the solution, how, by when */
function onePage(M,link){
  return '<div style="font:14px/1.5 Inter,Arial,sans-serif;color:'+INK+'">'+
    '<p style="margin:0 0 4px;font:600 11px/1 Inter,Arial,sans-serif;letter-spacing:.08em;text-transform:uppercase;color:'+IND+'">BrightYard blueprint</p>'+
    '<h1 style="font:600 24px/1.2 Inter,Arial,sans-serif;margin:0 0 6px">'+esc(M.title)+'</h1>'+
    '<p style="margin:0;color:'+MUTE+'">Live in about <b style="color:'+INK+'">'+M.minW+'–'+M.maxW+' weeks</b> · '+esc(M.complexity)+' complexity'+(M.start?' · starting '+esc(M.start):'')+'</p>'+
    h2('1. What we heard')+'<p style="margin:0 0 8px;color:'+MUTE+';font-style:italic">“'+esc(M.brief)+'”</p>'+
    ul(M.problems.map(function(p){return '<b>'+esc(p.text)+'</b>'+(p.stated?'':' <span style="color:#8A5A00">(our assumption, to confirm)</span>')+'<br><span style="color:'+MUTE+'">'+esc(p.why)+'.</span>'}))+
    h2('2. The solution')+'<p style="margin:0 0 8px">'+esc(M.summary)+'</p>'+
    ul(M.parts.map(function(c){return '<b>'+esc(c.name)+'</b>'+(c.fixes.length?'<br><span style="color:'+MUTE+'">Fixes: '+esc(c.fixes.join('; ').toLowerCase())+'</span>':'')}))+
    h2('3. How we build it')+rows(M.stages.map(function(s){return [s.name,s.when+' · '+s.agents+' agent'+(s.agents===1?'':'s')]}))+
    '<p style="margin:8px 0 0;color:'+MUTE+'">AI agents carry out '+M.coverage+'% of the work. An engineer reviews every change'+(M.gates.length?' and signs off at '+esc(M.gates.join(', ').toLowerCase()):'')+'.</p>'+
    h2('4. By when')+rows(M.milestones.map(function(m){return [m.name,m.when]}))+
    (M.metrics.length?'<p style="margin:10px 0 0"><b>We\'ll measure:</b> '+esc(M.metrics.slice(0,3).join('; '))+'.</p>':'')+
    (link?'<p style="margin:18px 0 0"><a href="'+esc(link)+'" style="color:'+IND+';font-weight:600">Open the interactive 3D blueprint</a></p>':'')+
    '<p style="margin:14px 0 0;font-size:12px;color:'+MUTE+'">Indicative only. A short discovery workshop confirms scope, cost and timing.</p></div>';
}
/* the extra detail for the full plan */
function fullPlan(M){
  var s='';
  if(M.outcomes.length)s+=h2('Expected outcomes')+ul(M.outcomes.map(esc));
  if(M.metrics.length)s+=h2('How we\'ll measure it')+ul(M.metrics.map(esc));
  s+=h2('Who does the work')+'<p style="margin:0">'+esc(M.agents.join(', '))+'.</p><p style="margin:6px 0 0;color:'+MUTE+'">Reviewed and approved by: '+esc(M.people.join(', ').toLowerCase())+'.</p>';
  if(M.assumptions.length)s+=h2('Assumptions to confirm')+ul(M.assumptions.map(esc));
  if(M.risks.length)s+=h2('Watch-outs')+ul(M.risks.slice(0,5).map(esc));
  return '<div style="font:14px/1.5 Inter,Arial,sans-serif;color:'+INK+'">'+s+'</div>';
}
function text(M,link){
  var L=[];L.push('BrightYard blueprint: '+M.title,'Live in about '+M.minW+'–'+M.maxW+' weeks'+(M.start?', starting '+M.start:''),'');
  L.push('1. WHAT WE HEARD','"'+M.brief+'"');M.problems.forEach(function(p){L.push('- '+p.text+(p.stated?'':' (our assumption, to confirm)'))});
  L.push('','2. THE SOLUTION',M.summary);M.parts.forEach(function(c){L.push('- '+c.name)});
  L.push('','3. HOW WE BUILD IT');M.stages.forEach(function(s){L.push('- '+s.name+': '+s.when)});
  L.push('','4. BY WHEN');M.milestones.forEach(function(m){L.push('- '+m.name+': '+m.when)});
  if(link)L.push('','Interactive 3D blueprint: '+link);
  L.push('','Indicative only. A short discovery workshop confirms scope, cost and timing.');
  return L.join('\n');
}
function b64url(s){
  var b=typeof btoa==='function'?btoa(unescape(encodeURIComponent(s))):Buffer.from(s,'utf8').toString('base64');
  return b.replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
}
function unb64url(s){
  s=String(s).replace(/-/g,'+').replace(/_/g,'/');while(s.length%4)s+='=';
  return typeof atob==='function'?decodeURIComponent(escape(atob(s))):Buffer.from(s,'base64').toString('utf8');
}
/* share link: the brief and the start date live in the URL, so the plan regenerates anywhere */
function link(base,brief,startISO){return base.replace(/#.*$/,'')+'#/plan/'+b64url(JSON.stringify({b:brief,s:startISO||''}))}
function readLink(hash){var m=/^#\/plan\/([A-Za-z0-9_-]+)/.exec(hash||'');if(!m)return null;try{var o=JSON.parse(unb64url(m[1]));return o&&typeof o.b==='string'?{brief:o.b.slice(0,4000),start:/^\d{4}-\d{2}-\d{2}$/.test(o.s||'')?o.s:''}:null}catch(e){return null}}
return {model:model,onePage:onePage,fullPlan:fullPlan,text:text,link:link,readLink:readLink,esc:esc};
})();

export default BYBrief;
